<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DVD Logo</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background: #1a1a2e;
        }
        canvas {
            display: block;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        // DVD Logo text
        let logoText = "DVD";
        let fontSize = 60;
        let x = 100;
        let y = 300;
        let velocityX = 5;
        let velocityY = 0;
        let gravity = 0.2;
        let bounceMultiplier = 0.8;
        let wallThickness = 40;

        // Draw the DVD logo
        function drawLogo() {
            ctx.font = `${fontSize}px Arial`;
            ctx.fillStyle = '#ffffff';
            ctx.textAlign = 'center';
            ctx.fillText(logoText, x, y);
        }

        // Check collision with walls
        function checkCollision() {
            if (x + fontSize / 2 > canvas.width - wallThickness) {
                velocityX *= -bounceMultiplier;
                x = canvas.width - wallThickness - fontSize / 2;
            }
            if (y + fontSize / 2 > canvas.height - wallThickness) {
                velocityY *= -bounceMultiplier;
                y = canvas.height - wallThickness - fontSize / 2;
            }
        }

        // Update position
        function updatePosition() {
            x += velocityX;
            y += velocityY;
            velocityY += gravity;
            checkCollision();
        }

        // Main loop
        function gameLoop() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            drawLogo();
            updatePosition();
            requestAnimationFrame(gameLoop);
        }

        // Start the game loop
        gameLoop();
    </script>
</body>
</html>
